 "allOf": [
  {
   "description": "Conditional applicability of D 11 damp heat tests (R60-2 §2.10.6):\nt08 (steady state) applies iff humidity_class = SH;\nt09 (cyclic) applies iff humidity_class = CH.\n",
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "humidity_class": {
          "const": "SH"
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "contains": {
       "properties": {
        "test_id": {
         "const": "d011_t08_damp_heat_steady_state"
        }
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "humidity_class": {
          "const": "CH"
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "contains": {
       "properties": {
        "test_id": {
         "const": "d011_t09_damp_heat_cyclic"
        }
       }
      }
     }
    }
   }
  },
  {
   "description": "Conducted/radiated EM tests apply only to analogue-active and\ndigital-active load cells per R60-2 §2.10.7.\n",
   "if": {
    "properties": {
     "certified_type": {
      "properties": {
       "module_designation": {
        "enum": [
         "analog_passive",
         "digital_passive"
        ]
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "not": {
       "contains": {
        "properties": {
         "test_id": {
          "enum": [
           "d011_t18_dc_mains_voltage_variation",
           "d011_t20_ac_mains_voltage_variation",
           "d011_t22_dc_mains_dips_interruptions",
           "d011_t23_ac_mains_dips_interruptions",
           "d011_t26_bursts_ac_dc_mains",
           "d011_t27_surges_ac_dc_mains",
           "d011_t28_bursts_signal_data_control",
           "d011_t29_surges_signal_data_control",
           "d011_t33_rf_em_fields_general",
           "d011_t35_electrostatic_discharges"
          ]
         }
        }
       }
      }
     }
    }
   }
  }
 ],
