 "allOf": [
  {
   "description": "D 11 §9.2 damp-heat tests apply per humidity class:\nH2 → t08 (steady state); H3 → t09 (cyclic).\n",
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "humidity_class": {
          "properties": {
           "value": {
            "const": "H2"
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "contains": {
       "properties": {
        "test_id": {
         "const": "d011_t08_damp_heat_steady_state"
        }
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "humidity_class": {
          "properties": {
           "value": {
            "const": "H3"
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "contains": {
       "properties": {
        "test_id": {
         "const": "d011_t09_damp_heat_cyclic"
        }
       }
      }
     }
    }
   }
  }
 ],
