  "PressureReference": {
   "description": "R137-1 §4.1.2 pressure reference qualifier. Gas meter pressure\nspecifications may be expressed relative to atmospheric pressure\n(gauge) or against vacuum (absolute), or as a difference between\ntwo measurement points (differential). This is an R137-specific\naspect — distinct from the D 11 environmental classes and not\npart of the D 11 module.\n",
   "type": "string",
   "oneOf": [
    {
     "const": "gauge",
     "description": "Gauge pressure — measured relative to atmospheric pressure (e.g. bar(g))"
    },
    {
     "const": "absolute",
     "description": "Absolute pressure — measured against vacuum (e.g. bar(a))"
    },
    {
     "const": "differential",
     "description": "Differential pressure — measured between two points (e.g. ΔP across the meter)"
    }
   ]
  },
