 "allOf": [
  {
   "description": "Conditional applicability of D 11 damp heat tests (R137 references\nD 11 §9.2 for humidity performance):\nt08 (steady state) applies when the meter is rated for non-condensing\n(stable humidity) conditions;\nt09 (cyclic) applies when the meter is rated for condensing humidity.\nThe environmental class H1/H2/H3 determines which applies.\n",
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "climatic_environment_class": {
          "properties": {
           "value": {
            "const": "H1"
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "contains": {
       "properties": {
        "test_id": {
         "const": "d011_t08_damp_heat_steady_state"
        }
       }
      }
     }
    }
   }
  },
  {
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "climatic_environment_class": {
          "properties": {
           "value": {
            "const": "H2"
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "contains": {
       "properties": {
        "test_id": {
         "const": "d011_t09_damp_heat_cyclic"
        }
       }
      }
     }
    }
   }
  },
  {
   "description": "Conducted/radiated EM and mains tests apply only to meters with\nelectronic components (powered meters). Purely mechanical meters\n(mechanical diaphragm meters without electronics) are exempt from\nD 11 §11-§12 tests per R137-1 §3.2.\n",
   "if": {
    "properties": {
     "characteristics": {
      "properties": {
       "type_level": {
        "properties": {
         "power_supply_type": {
          "properties": {
           "value": {
            "const": "mechanical"
           }
          }
         }
        }
       }
      }
     }
    }
   },
   "then": {
    "properties": {
     "d011_tests_applicable": {
      "not": {
       "contains": {
        "properties": {
         "test_id": {
          "enum": [
           "d011_t18_dc_mains_voltage_variation",
           "d011_t20_ac_mains_voltage_variation",
           "d011_t22_dc_mains_dips_interruptions",
           "d011_t23_ac_mains_dips_interruptions",
           "d011_t26_bursts_ac_dc_mains",
           "d011_t27_surges_ac_dc_mains",
           "d011_t28_bursts_signal_data_control",
           "d011_t29_surges_signal_data_control",
           "d011_t33_rf_em_fields_general",
           "d011_t35_electrostatic_discharges"
          ]
         }
        }
       }
      }
     }
    }
   }
  }
 ],
